export const meta = {
  name: 'vishnujayvel-new-six-review',
  description: 'Review the six never-reviewed vishnujayvel PRs, verify each finding adversarially, and draft a review body per PR',
  phases: [
    { title: 'Review', detail: 'one reviewer per PR, produces findings + draft review body' },
    { title: 'Verify', detail: 'adversarial refutation of each finding before it can be posted' },
  ],
}

const SCRATCH = '/tmp/claude-1000/-var-home-matt-dev-mybd/e9351284-9274-4fb0-bf3a-a5bee6195a19/scratchpad'

const PRS = [
  { n: 5136, title: 'fix(init): verify refs/dolt/data before remote-history claims' },
  { n: 5137, title: 'fix(doctor): require corroboration before flagging test pollution' },
  { n: 5138, title: 'fix(epic): do not treat duplicate/wontfix closes as completion' },
  { n: 5139, title: 'fix(prime): detect git remote from CWD, not BEADS_DIR' },
  { n: 5140, title: 'fix(dolt): include config table when explicitly committing' },
  { n: 5141, title: 'fix(export): stop auto-export guards from wedging on stale state' },
]

const FINDINGS = {
  type: 'object',
  required: ['pr', 'diagnosis_correct', 'fix_correct', 'findings', 'recommendation'],
  properties: {
    pr: { type: 'number' },
    diagnosis_correct: { type: 'string', description: 'YES / NO / PARTIAL plus one sentence' },
    fix_correct: { type: 'string', description: 'YES / NO / PARTIAL plus one sentence — is the fix at the right layer, right breadth, does it cover the error branches' },
    findings: {
      type: 'array',
      items: {
        type: 'object',
        required: ['severity', 'file_line', 'claim', 'failure_scenario'],
        properties: {
          severity: { type: 'string', description: 'blocker | should-fix | nit' },
          file_line: { type: 'string' },
          claim: { type: 'string' },
          failure_scenario: { type: 'string', description: 'concrete inputs/state leading to wrong behaviour' },
        },
      },
    },
    recommendation: { type: 'string', description: 'approve | approve-with-followups | comment-with-findings | needs-design-discussion, plus one sentence' },
    body_file: { type: 'string', description: 'absolute path of the draft review markdown written' },
  },
}

const VERDICT = {
  type: 'object',
  required: ['refuted', 'reason'],
  properties: {
    refuted: { type: 'boolean' },
    reason: { type: 'string' },
    corrected_claim: { type: 'string' },
  },
}

const CONTEXT = `
Repository: gastownhall/beads. Source checkout (READ-ONLY, do not edit, do not commit): /var/home/matt/dev/mybd/bd-main
Author: vishnujayvel, a high-volume contributor. Observed pattern from the previous wave: diagnoses are now mostly CORRECT; the failure mode has shifted to fix BREADTH and PLACEMENT — e.g. a hoist that skips the error branch, a fix applied in the test rather than the code, a fix in the wrong direction, or a generator that emits unparseable output. Look hardest there.
Maintainer policy: maximize contributor throughput. Find the real value and absorb or transform it; request-changes is a last resort. A verified blocker is still worth stating plainly, but frame it as something we will help land.
Use the gh CLI read-only to fetch the diff and discussion. NEVER post anything upstream — no gh pr review, no gh pr comment, no gh pr merge. You draft only.
`

phase('Review')

const results = await pipeline(
  PRS,
  (pr) => agent(`${CONTEXT}
Review gastownhall/beads#${pr.n} — "${pr.title}". It has never had a maintainer review.

Steps:
1. gh pr view ${pr.n} --repo gastownhall/beads --json title,body,files,additions,deletions,commits and gh pr diff ${pr.n} --repo gastownhall/beads
2. Read the ACTUAL surrounding code in /var/home/matt/dev/mybd/bd-main, not just the diff hunks. Verify the bug the PR claims to fix really exists on current main, and that the fix actually closes it.
3. Judge fix breadth and placement specifically: does it cover error branches and early returns; is it at the right layer; does it fix the symptom in a test instead of the cause; does it change behaviour the description does not mention; does it break an existing caller.
4. Check whether the PR duplicates or collides with other open work: gh pr list --repo gastownhall/beads --state open --search "<topic keywords>".
5. Write a maintainer review body in Markdown to ${SCRATCH}/pr${pr.n}-review.md. Requirements for that file: lead with the disposition; state findings with file:line and a concrete failure scenario; be warm and specific, not a checklist; no literal backslash-n sequences (write real newlines); refer to PRs as #1234 form; end with exactly this signature line on its own: _claude-opus-5-medium on behalf of maphew_
6. Return the structured findings.

Report only what you verified against code. If you could not verify a claim, say so rather than asserting it.`,
    { label: `review:${pr.n}`, phase: 'Review', schema: FINDINGS }),

  (review, pr) => {
    if (!review || !Array.isArray(review.findings) || review.findings.length === 0) {
      return { review, verified: [], dropped: 0 }
    }
    const serious = review.findings.filter(f => f && f.severity !== 'nit')
    return parallel(serious.map(f => () =>
      agent(`${CONTEXT}
Adversarially verify ONE review finding about gastownhall/beads#${pr.n}. Your job is to REFUTE it. Default to refuted=true if you cannot confirm it against the actual code.

Finding severity: ${f.severity}
Location: ${f.file_line}
Claim: ${f.claim}
Alleged failure scenario: ${f.failure_scenario}

Read the real code at /var/home/matt/dev/mybd/bd-main and the PR diff (gh pr diff ${pr.n} --repo gastownhall/beads). Check specifically: does the cited file:line say what the claim says it says; does the failure scenario actually reach that code; is there an existing guard, caller contract, or later branch that already prevents it; is the claim about behaviour that main already has (so not introduced by this PR). Return refuted true/false with a reason, and a corrected_claim if the finding is real but stated wrongly.`,
        { label: `verify:${pr.n}:${(f.file_line || '').slice(0, 24)}`, phase: 'Verify', schema: VERDICT })
        .then(v => ({ finding: f, verdict: v }))
    )).then(votes => {
      const good = votes.filter(Boolean)
      const survived = good.filter(v => v.verdict && v.verdict.refuted === false)
      return {
        pr: pr.n,
        review,
        body_file: review.body_file || `${SCRATCH}/pr${pr.n}-review.md`,
        recommendation: review.recommendation,
        diagnosis_correct: review.diagnosis_correct,
        fix_correct: review.fix_correct,
        verified_findings: survived.map(v => ({ ...v.finding, corrected: v.verdict.corrected_claim })),
        refuted_findings: good.filter(v => v.verdict && v.verdict.refuted === true)
          .map(v => ({ file_line: v.finding.file_line, claim: v.finding.claim, why_refuted: v.verdict.reason })),
        nits: review.findings.filter(f => f && f.severity === 'nit').length,
        dropped: serious.length - good.length,
      }
    })
  }
)

const clean = results.filter(Boolean)
log(`reviewed ${clean.length}/${PRS.length} PRs`)
for (const r of clean) {
  if (r && r.dropped) log(`PR ${r.pr}: ${r.dropped} verification agent(s) failed and were dropped`)
}

return {
  reviewed: clean.length,
  attempted: PRS.length,
  prs: clean.map(r => r && r.review ? {
    pr: r.pr,
    body_file: r.body_file,
    recommendation: r.recommendation,
    diagnosis_correct: r.diagnosis_correct,
    fix_correct: r.fix_correct,
    verified: r.verified_findings,
    refuted_count: (r.refuted_findings || []).length,
    refuted: r.refuted_findings,
    nits: r.nits,
  } : r),
}
